// План specs/addresses.md 1.2 (кейс AD-02). Admin, компания «test». Форму не сохраняем. Зависит от Google Places.
import { test, expect } from '@playwright/test';
import { ADMIN_STATE, addressInput, openNewJobAddressDetails, setEnglish, typeAndPickSuggestion, unitInput } from './address-helpers';

test.use({ storageState: ADMIN_STATE });

const CASES = [
  { kind: 'Unit', typed: '100 Main St Unit 12 Boston', main: '100 Main St unit 12', secondary: 'Boston, MA, USA', unit: 'Unit 12', zip: '02129', leftover: /unit\s*12/i },
  { kind: 'Suite', typed: '350 5th Ave Suite 3300 New York', main: '350 5th Ave suite 3300', secondary: 'New York, NY, USA', unit: 'Suite 3300', zip: '10118', leftover: /suite\s*3300/i },
  { kind: 'Ste', typed: '1 Infinite Loop Ste 200 Cupertino', main: '1 Infinite Loop ste 200', secondary: 'Cupertino, CA, USA', unit: 'Suite 200', zip: '95014', leftover: /ste\s*200|suite\s*200/i },
  { kind: '#', typed: '2221 NW Federal Hwy #5B', main: '2221 NW Federal Hwy #5b', secondary: 'Stuart, FL, USA', unit: '#5B', zip: '34994', leftover: /#\s*5b/i },
];

test.describe('Адрес: Unit / Suite / Ste / # → Unit/Apt (#8ffd6e26)', () => {
  for (const c of CASES) {
    test(`New Job: "${c.kind}" in the address moves to Unit/Apt as "${c.unit}" #8ffd6e26 @desktop @prod-safe @google-places`, async ({ page }) => {
      await setEnglish(page);
      await openNewJobAddressDetails(page);

      await typeAndPickSuggestion(page, c.typed, c.main, c.secondary);

      await expect(unitInput(page)).toHaveValue(c.unit);
      // ZIP приходит ~1 с после выбора — ждём значение как признак, что адрес разобран полностью.
      await expect(page.getByLabel('ZIP Code', { exact: true })).toHaveValue(c.zip);
      await expect(addressInput(page)).not.toHaveValue(c.leftover);
    });
  }
});
